selector_to_html = {"a[href=\"#tracing-vs-video\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Tracing vs Video<a class=\"headerlink\" href=\"#tracing-vs-video\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#use-descriptive-filenames\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. Use Descriptive Filenames<a class=\"headerlink\" href=\"#use-descriptive-filenames\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#limitations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Limitations<a class=\"headerlink\" href=\"#limitations\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#overlay-api-summary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Overlay API Summary<a class=\"headerlink\" href=\"#overlay-api-summary\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#best-practices\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Best Practices<a class=\"headerlink\" href=\"#best-practices\" title=\"Link to this heading\">#</a></h2><h3>1. Use Descriptive Filenames<a class=\"headerlink\" href=\"#use-descriptive-filenames\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#basic-recording\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Basic Recording<a class=\"headerlink\" href=\"#basic-recording\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#video-recording\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Video Recording<a class=\"headerlink\" href=\"#video-recording\" title=\"Link to this heading\">#</a></h1><p>Capture browser automation sessions as video for debugging, documentation, or verification. Produces WebM (VP8/VP9 codec).</p>", "a[href=\"#record-entire-hero-scripts\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. Record entire hero scripts.<a class=\"headerlink\" href=\"#record-entire-hero-scripts\" title=\"Link to this heading\">#</a></h3><p>When recording a video for the user or as a proof of work, it is best to create a code snippet and execute it with run-code.\nIt allows pulling appropriate pauses between the actions and annotating the video. There are new Playwright APIs for that.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
